-- Verify date_trunc, age and date_bin of timestamp, and the ISO week fields,
-- which ty does (ty/DESIGN.md section 19).
-- (Errors are server.sh's: a run stops at its first.)
SELECT u, date_trunc(u, t)::text FROM (VALUES ('microseconds'), ('milliseconds'), ('second'), ('minute'), ('hour'), ('day'), ('week'), ('month'), ('quarter'), ('year'), ('decade'), ('century'), ('millennium'), ('YEAR'), ('Week')) a(u), (VALUES ('2024-02-29 13:45:56.789012'::timestamp), ('2021-01-03 10:00:00'), ('2020-12-31 23:59:59.999999'), ('0044-03-15 12:00:00 BC'), ('0001-01-01 00:00:00'), ('1999-12-27 08:30:00'), ('infinity'), ('-infinity')) b(t) ORDER BY 1, 2;
SELECT a::text, b::text, age(a, b)::text, age(b, a)::text FROM (VALUES ('2024-02-29 13:45:56.789012'::timestamp), ('2000-01-31 00:00:00'), ('1999-03-01 23:59:59.5'), ('0100-02-28 00:00:00 BC'), ('infinity'), ('-infinity')) x(a), (VALUES ('2000-03-31 12:00:00'::timestamp), ('2023-12-31 23:59:59.999999'), ('1950-02-28 01:02:03.456789'), ('2024-02-29 13:45:56.789012')) y(b) ORDER BY 1, 2;
SELECT s, t, date_bin(s, t, '2001-01-01 00:00:00')::text FROM (VALUES ('15 minutes'::interval), ('1 hour'), ('1 day'), ('7 days'), ('1 second'), ('1 microsecond'), ('1 day 12 hours')) a(s), (VALUES ('2024-02-29 13:47:56.789012'::timestamp), ('1990-06-15 03:20:00'), ('2001-01-01 00:00:00'), ('2000-12-31 23:59:59.999999'), ('infinity')) b(t) ORDER BY 1, 2;
SELECT d::text, extract(isoyear FROM d), extract(week FROM d), extract(doy FROM d), extract(isodow FROM d), to_char(d, 'IYYY-IW-ID'), date_trunc('week', d)::text FROM generate_series('2020-12-25'::date, '2021-01-10'::date, '1 day') g(d);
SELECT d::text, extract(isoyear FROM d), extract(week FROM d), date_trunc('week', d)::text FROM generate_series('2024-12-23'::date, '2025-01-08'::date, '1 day') g(d);
